#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#define N 16
static const char* map[N]={"################","#..............#","#.##..###..###.#","#.##..###..###.#","#..............#","#..............#","#.###..##..###.#","#.###..##..###.#","#..............#","#..............#","#.##..###..###.#","#.##..###..###.#","#..............#","#..###....###..#","#..............#","################"};
typedef struct {float x,y,a; bool keys[6],car,quit; unsigned cash,mission; FuriMessageQueue* q; FuriMutex* lock;} Game;
static bool wall(float x,float y){int a=(int)x,b=(int)y;return x<0||y<0||a>=N||b>=N||map[b][a]=='#';}
static void draw(Canvas* c,void* ctx){Game* g=ctx;furi_mutex_acquire(g->lock,FuriWaitForever);canvas_clear(c);float dx=cosf(g->a),dy=sinf(g->a);float cx=g->x,cy=g->y;for(float d=.1f;d<.9f;d+=.1f){if(wall(g->x-d*dx,g->y-d*dy))break;cx=g->x-d*dx;cy=g->y-d*dy;}
for(int x=0;x<128;x+=2){float off=(x-64)/64.f*.65f;float rx=dx-dy*off,ry=dy+dx*off;float d=.05f;while(d<15&&!wall(cx+rx*d,cy+ry*d))d+=.045f;int h=(int)(35/d);if(h>52)h=52;int top=28-h/2;canvas_draw_line(c,x,top,x,top+h);if(((int)((cx+rx*d)*8)+(int)((cy+ry*d)*8))%3==0)canvas_draw_line(c,x+1,top,x+1,top+h);}
for(int i=0;i<4;i++){int y=35+i*i*2;canvas_draw_line(c,62,y,65,y);}
canvas_set_color(c,ColorWhite);canvas_draw_box(c,54,32,20,21);canvas_set_color(c,ColorBlack);if(g->car){canvas_draw_rbox(c,54,35,20,17,2);canvas_set_color(c,ColorWhite);canvas_draw_box(c,58,38,12,5);canvas_set_color(c,ColorBlack);}else{canvas_draw_disc(c,64,35,3);canvas_draw_box(c,60,39,8,7);canvas_draw_line(c,60,40,56,45);canvas_draw_line(c,67,40,71,45);canvas_draw_line(c,62,46,59,52);canvas_draw_line(c,66,46,69,52);}
canvas_set_color(c,ColorWhite);canvas_draw_box(c,0,0,128,9);canvas_draw_box(c,0,54,128,10);canvas_set_color(c,ColorBlack);canvas_set_font(c,FontSecondary);char s[40];snprintf(s,sizeof(s),"$%u  %s",g->cash,g->car?"DRIVE":"WALK");canvas_draw_str(c,1,8,s);canvas_draw_str(c,1,63,"HP100");snprintf(s,sizeof(s),"M%u: %d,%d",g->mission+1, g->mission%2?1:14,g->mission%2?1:14);canvas_draw_str(c,48,63,s);canvas_draw_frame(c,105,10,22,22);for(int y=0;y<N;y++)for(int x=0;x<N;x++)if(map[y][x]=='#')canvas_draw_dot(c,108+x,13+y);canvas_draw_disc(c,108+(int)g->x,13+(int)g->y,1);furi_mutex_release(g->lock);}
static void input(InputEvent* e,void* ctx){Game* g=ctx;furi_message_queue_put(g->q,e,0);}
int32_t gta_main(void* p){UNUSED(p);Game* g=calloc(1,sizeof(Game));if(!g)return -1;g->x=1.5f;g->y=1.5f;g->q=furi_message_queue_alloc(16,sizeof(InputEvent));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);ViewPort* v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,g);Gui* gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);while(!g->quit){InputEvent e;bool got=furi_message_queue_get(g->q,&e,30)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);if(got){if(e.key==InputKeyBack&&e.type==InputTypeShort)g->quit=true;if(e.key==InputKeyOk&&e.type==InputTypeShort)g->car=!g->car;if(e.key<6){if(e.type==InputTypePress)g->keys[e.key]=true;if(e.type==InputTypeRelease)g->keys[e.key]=false;}}if(g->keys[InputKeyLeft])g->a-=.09f;if(g->keys[InputKeyRight])g->a+=.09f;float speed=(g->car?.15f:.07f)*(g->keys[InputKeyUp]-g->keys[InputKeyDown]);float x=g->x+cosf(g->a)*speed,y=g->y+sinf(g->a)*speed;if(!wall(x,g->y))g->x=x;if(!wall(g->x,y))g->y=y;float target=g->mission%2?1.5f:14.5f;if(fabsf(g->x-target)<.6f&&fabsf(g->y-target)<.6f){g->cash+=250;g->mission++;}furi_mutex_release(g->lock);view_port_update(v);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}